import numpy as np
e=df['eps'].values;t=df['T'].values;s=df['sigma'].values
def fit(cols):
    A=np.column_stack(cols); c=np.linalg.lstsq(A,s,rcond=None)[0]; r=s-A@c
    return c, np.mean(r**2)/np.var(s)
for d in range(2,7):
    cols=[e**i*t**j for i in range(d+1) for j in range(4) if i+j<=d]
    c,nm=fit(cols); print(d,nm)
# additive form: f(e)+g(T)
for d in range(2,8):
    cols=[e**i for i in range(d+1)]+[t**j for j in range(1,4)]
    c,nm=fit(cols); print('add',d,nm)

import numpy as np
e=df['eps'].values;t=df['T'].values;s=df['sigma'].values
def nm(cols):
    A=np.column_stack(cols); c=np.linalg.lstsq(A,s,rcond=None)[0]; r=s-A@c
    return np.mean(r**2)/np.var(s)
for name,g in [('invT',1/t),('logT',np.log(t)),('sqrtT',np.sqrt(t)),('expT',np.exp(-t))]:
    for d in [4,5,6]:
        cols=[e**i*g**j for i in range(d+1) for j in range(4) if i+j<=d]
        print(name,d,nm(cols))
# eps-basis: log, sqrt
for d in [4,5,6]:
    cols=[e**i*t**j for i in range(d+1) for j in range(4) if i+j<=d]+[np.log(e)*t**j for j in range(4)]+[np.log(e)*e**i for i in range(1,4)]
    print('log',d,nm(cols))
